      { de = "Der da? Nicht allein, {Held|Heldin}.", en = "That one? Not alone, hero.", stimme = "gefahr_elite-1", wenn = nil },
      { de = "{name}. Elite. Um den herum ist auch noch Land.", en = "{name}. Elite. There's plenty of land around it, too.", stimme = nil, wenn = nil },
      { de = "Der hat mehr Leben als du Geduld, {Süßer|Süße}. Nicht jetzt.", en = "That one has more health than you have patience, sweetie. Not now.", stimme = "gefahr_elite-2", wenn = nil },
      { de = "Elite. Mit Gruppe ein Kampf, allein ein Nachruf.", en = "Elite. With a group, a fight. Alone, an obituary.", stimme = "gefahr_elite-3", wenn = nil },
      { de = "Ich seh die Runen um den. Dick. Lass ihn, {mein Lieber|meine Liebe}.", en = "I see the runes around that one. Thick ones. Leave it, my dear.", stimme = "gefahr_elite-4", wenn = nil },
      { de = "Das ist kein Ziel, das ist eine Entscheidung. Triff die richtige.", en = "That's not a target, that's a decision. Make the right one.", stimme = "gefahr_elite-5", wenn = nil },
    } },
    GEFAHR_STUFEN = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "anxious", pose = nil, halte = 15, cue = nil, drossel = "name-session", texte = {
      { de = "Drei Stufen über dir. Deine Zauber verfehlen, seine nicht.", en = "Three levels above you. Your spells miss, his don't.", stimme = "gefahr_stufen-1", wenn = nil },
      { de = "Zu hoch für dich. Nicht deine Ehre, deine Stufe.", en = "Too high for you. Not your pride, your level.", stimme = "gefahr_stufen-2", wenn = nil },
      { de = "{name} ist dir Stufen voraus. Warte, bis du aufgeholt hast.", en = "{name} is levels ahead of you. Wait until you've caught up.", stimme = nil, wenn = nil },
      { de = "Deine Runen greifen da nicht. Seine schon. Weitergehen.", en = "Your runes won't bite there. His will. Keep walking.", stimme = "gefahr_stufen-3", wenn = nil },
      { de = "Stufen sind keine Meinung, {Held|Heldin}. Der ist stärker.", en = "Levels aren't an opinion, hero. That one's stronger.", stimme = "gefahr_stufen-4", wenn = nil },
      { de = "Erst wachsen, dann streiten. Ich hab Zeit, du auch.", en = "Grow first, fight later. I've got time. So do you.", stimme = "gefahr_stufen-5", wenn = nil },
    } },
    GEOFENCE = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "alert", pose = nil, halte = 15, cue = nil, drossel = "stelle-600", texte = {
      { de = "Hier sind schon welche gestürzt. Schritt für Schritt.", en = "People have fallen here before. One step at a time.", stimme = "geofence-1", wenn = nil },
      { de = "Vorsicht, Kante. Hier ist schon mancher gefallen. Langsam.", en = "Careful, edge. More than one has fallen here. Slowly.", stimme = "geofence-2", wenn = nil },
      { de = "Kante. Die Schwerkraft macht keine Ausnahmen, auch nicht für dich.", en = "Edge. Gravity doesn't make exceptions, not even for you.", stimme = "geofence-3", wenn = nil },
      { de = "Hier endet der Boden früher als die Karte. Langsam.", en = "The ground ends sooner than the map does here. Slowly.", stimme = "geofence-4", wenn = nil },
      { de = "Nicht springen, {Süßer|Süße}. Ich hab keinen Federfall dabei.", en = "Don't jump, sweetie. I didn't pack a slow fall.", stimme = "geofence-5", wenn = nil },
      { de = "Abgrund. Ich kenne die Namen der Gestürzten. Deinen will ich nicht lernen.", en = "A drop. I know the names of the fallen. I don't want to learn yours.", stimme = "geofence-6", wenn = nil },
      { de = "Zwei Schritte zurück, {mein Lieber|meine Liebe}. Die Aussicht ist von dort genauso gut.", en = "Two steps back, my dear. The view's just as good from there.", stimme = "geofence-7", wenn = nil },
    } },
    TRANK = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "upset", pose = nil, halte = 15, cue = nil, drossel = "1800", texte = {
      { de = "Letzter Heiltrank weg. Ohne Trank kein Heldentum.", en = "Last healing potion gone. No potion, no heroics.", stimme = "trank-1", wenn = nil },
      { de = "Kein Trank mehr. Ab jetzt ist Vorsicht deine einzige Heilung.", en = "No potions left. From now on caution is your only healing.", stimme = "trank-2", wenn = nil },
      { de = "Die Flasche war die letzte. Kaufen, bevor du mutig wirst.", en = "That bottle was the last one. Buy more before you get brave.", stimme = "trank-3", wenn = nil },
      { de = "Leer, {Held|Heldin}. Ohne Trank jagt man kleiner.", en = "Empty, hero. No potion means hunting smaller.", stimme = "trank-4", wenn = nil },
      { de = "Kein Heiltrank. Ich würde ja einen brauen, aber ich bin Dekoration.", en = "No healing potion. I'd brew one, but I'm decoration.", stimme = "trank-5", wenn = nil },
      { de = "Null Tränke, {Meister|Meisterin}. Das ist eine Zahl, die ich nicht mag.", en = "Zero potions, my dear. That's a number I don't like.", stimme = "trank-6", wenn = nil },
    } },
    BUFF_WEG = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "whatever", pose = nil, halte = 10, cue = "seufz", drossel = "buff-1800", texte = {
      { de = "{buff} ist verpufft.", en = "{buff} has fizzled.", stimme = nil, wenn = nil },
      { de = "Proviant verbraucht. Er kocht sich nicht von allein.", en = "Food's used up. It doesn't cook itself.", stimme = "buff_weg-1", wenn = nil },
      { de = "{buff} ist weg. Die Runen halten auch nicht ewig.", en = "{buff} is gone. Runes don't last forever either.", stimme = nil, wenn = nil },
      { de = "Da ist was abgelaufen. Ich sag's nur, ich zwinge dich nicht.", en = "Something just expired. Just saying, not forcing you.", stimme = "buff_weg-2", wenn = nil },
      { de = "Dein Zauber ist verblasst. Passiert den Besten. Mir nie.", en = "Your buff has faded. Happens to the best. Never to me.", stimme = "buff_weg-3", wenn = nil },
      { de = "Etwas Warmes um dich ist erloschen. Nachlegen, {Süßer|Süße}.", en = "Something warm around you went out. Top it up, sweetie.", stimme = "buff_weg-4", wenn = nil },
      { de = "Verpufft. Ich hab's gerochen. Wie kalter Weihrauch.", en = "Fizzled. I could smell it. Like cold incense.", stimme = "buff_weg-5", wenn = nil },
    } },
    BUFF_BALD = { klasse = "still", stufe = 0, gruppeOk = false, miene = "hmm", pose = nil, halte = 10, cue = nil, drossel = "buff", texte = {
    } },
    MUEDE = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "sad", pose = nil, halte = 20, cue = "gaehn", drossel = "3600", texte = {
      { de = "Du bist müde. Ich auch. Einer von uns sollte ins Gasthaus.", en = "You're tired. So am I. One of us should hit the inn.", stimme = "muede-1", wenn = nil },
      { de = "Kein Ausgeruht-Bonus mehr. Das Gasthaus ruft, leise.", en = "Rested bonus gone. The inn is calling, quietly.", stimme = "muede-2", wenn = nil },
      { de = "Du gähnst. Ich seh's nicht, ich weiß es trotzdem.", en = "You're yawning. I can't see it, I know it anyway.", stimme = "muede-3", wenn = nil },
      { de = "Müde Helden machen müde Fehler. Ein Bett, {mein Lieber|meine Liebe}.", en = "Tired heroes make tired mistakes. A bed, my dear.", stimme = "muede-4", wenn = nil },
      { de = "Dein Mana ist voll, dein Kopf ist leer. Pause, {Süßer|Süße}.", en = "Your mana's full, your head's empty. Break time, sweetie.", stimme = "muede-5", wenn = nil },
      { de = "Selbst Elementare ruhen. Also, sie tun so. Du solltest es echt tun.", en = "Even elementals rest. Well, they pretend to. You should do it for real.", stimme = "muede-6", wenn = nil },
    } },
    RAST_AN = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 0, cue = nil, drossel = "session", texte = {
      { de = "Gasthaus. Endlich. Bestell mir nichts, ich trinke nur Mana.", en = "An inn. Finally. Don't order for me, I only drink mana.", stimme = "rast_an-1", wenn = nil },
      { de = "Warm hier. Ich setz mich in Gedanken an den Kamin.", en = "Warm in here. I'm sitting by the fire, in my mind.", stimme = "rast_an-2", wenn = nil },
      { de = "Ausruhen, {Held|Heldin}. Die Welt draußen wartet gern.", en = "Rest up, hero. The world outside is happy to wait.", stimme = "rast_an-3", wenn = nil },
      { de = "Ein Wirtshaus. Die Leylinien machen hier einen Bogen, wusstest du das?", en = "An inn. The ley lines curve around this place, did you know that?", stimme = "rast_an-4", wenn = nil },
      { de = "Sicher. Zumindest vor allem außer schlechtem Bier.", en = "Safe. From everything except bad ale, anyway.", stimme = "rast_an-5", wenn = nil },
      { de = "Hier passiert nichts, {mein Lieber|meine Liebe}. Genieß das, es ist selten.", en = "Nothing happens here, my dear. Enjoy that, it's rare.", stimme = "rast_an-6", wenn = nil },
      { de = "Setz dich hin. Sofort. Und beweg dich die nächsten zehn Minuten nicht.", en = "Sit down. Now. And don't move for the next ten minutes.", stimme = "rast_an-7", wenn = { laune = "besorgt" } },
      { de = "Endlich ein Dach. Du bist seit Stunden unterwegs, falls du es vergessen hast.", en = "A roof at last. You've been out for hours, in case you'd forgotten.", stimme = "rast_an-8", wenn = { sitzung = 3 } },
      { de = "Gasthaus. Warm. Du. Wenn du das je jemandem erzählst, leugne ich alles.", en = "An inn. Warm. You. If you ever tell anyone I said this, I'll deny all of it.", stimme = "rast_an-9", wenn = { vertraut = 3 } },
      { de = "Sitz. Und solange du sitzt: {erinnerung}.", en = "Sit. And while you're sitting: {erinnerung}.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Dach über dem Kopf. Gute Gelegenheit für {erinnerung}, finde ich.", en = "A roof overhead. Good moment for {erinnerung}, I'd say.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Du suchst dir immer den Platz am Feuer. Jedes Mal. Ich sage es nur.", en = "You always pick the seat by the fire. Every time. Just saying.", stimme = "rast_an-10", wenn = { vertraut = 1 } },
      { de = "Rast. Du hältst es inzwischen länger hier aus als früher. Das ist Fortschritt.", en = "Rest. You last longer in here than you used to. That's progress.", stimme = "rast_an-11", wenn = { vertraut = 2 } },
      { de = "Endlich sitzt du. Ich zähle das als Sieg.", en = "You're finally sitting. I'm counting that as a win.", stimme = "rast_an-12", wenn = nil },
      { de = "Hier drinnen gibt es kein Wetter und niemanden mit Zähnen. Bleib eine Weile.", en = "No weather in here, and nobody with teeth. Stay a while.", stimme = "rast_an-13", wenn = nil, selten = true },
      { de = "Erste Rast im Gasthaus. Setz dich. Ich pass auf.", en = "First rest at an inn. Sit down. I'll keep watch.", stimme = "rast_an-14", wenn = nil, k = "w15_erste_rast", einmal = true },
      { de = "Nur wir zwei. Passt schon.", en = "Just the two of us. That's fine.", stimme = "rast_an-15", wenn = { p_allein = "allein" } },
      { de = "Vorsichtig, hast du gesagt. Merkt man.", en = "Careful, you said. Shows.", stimme = "rast_an-16", wenn = { p_mut = "vorsichtig" } },
    } },
    LEVELUP = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "overjoyed", pose = "victory", halte = 30, cue = "ohh", drossel = "level", texte = {
      { de = "Bei den Leylinien, {level}! Ich hab dir nichts davon abgenommen. Fast.", en = "By the ley lines, {level}! I didn't do any of that for you. Almost.", stimme = nil, wenn = nil },
      { de = "Bei den Leylinien, eine Stufe! Ich hab dir nichts davon abgenommen. Fast.", en = "By the ley lines, a level! I didn't do any of that for you. Almost.", stimme = "levelup-1", wenn = nil },
      { de = "Neue Zauber kaufen, nicht vergessen.", en = "New spells to buy. Don't forget.", stimme = "levelup-2", wenn = nil },
      { de = "Stufe {level}. Ich spüre es in den Runen. Und du im Geldbeutel, gleich.", en = "Level {level}. I feel it in the runes. You'll feel it in your purse, shortly.", stimme = nil, wenn = nil },
      { de = "Eine Stufe mehr, {Süßer|Süße}. Ich hab nur zugeschaut. Aufmerksam.", en = "One more level, sweetie. I just watched. Attentively.", stimme = "levelup-3", wenn = nil },
      { de = "Die Leylinien haben kurz gesungen. Das warst du.", en = "The ley lines sang for a moment. That was you.", stimme = "levelup-4", wenn = nil },
      { de = "Noch eine. Du machst das inzwischen immer in derselben Reihenfolge: aufsteigen, Taschen prüfen, weiterlaufen.", en = "Another one. You do this in the same order every time now: level, check bags, keep walking.", stimme = "levelup-5", wenn = { vertraut = 1 } },
      { de = "Eine Stufe mehr. Ich zähle seit deiner ersten mit, falls dich das interessiert.", en = "One more level. I've been counting since your first, in case you care.", stimme = "levelup-6", wenn = { vertraut = 1 } },
      { de = "Geschafft. Und du hältst dich immer noch für den vorsichtigen Typ.", en = "Done. And you still think of yourself as the careful type.", stimme = "levelup-7", wenn = { vertraut = 2 } },
      { de = "Aufgestiegen. Ich tue so, als hätte ich nichts bemerkt.", en = "Levelled. I'll pretend I didn't notice.", stimme = "levelup-8", wenn = nil },
      { de = "Eine Stufe. Kauf Zauber, bevor du es wieder vergisst.", en = "A level. Buy spells before you forget again.", stimme = "levelup-9", wenn = nil },
      { de = "Irgendwann kommt die letzte Stufe, und dann reden wir über etwas anderes. Heute noch nicht.", en = "One day there'll be a last level, and then we'll talk about something else. Not today.", stimme = "levelup-10", wenn = nil, selten = true },
      { de = "Mensch, keine Spezialfähigkeit außer Sturheit. Reicht bisher.", en = "Human. No special trick except stubbornness. Works so far.", stimme = "levelup-11", wenn = { rasse = "Human" } },
      { de = "Zwerg, kurze Beine, langer Atem. Noch nicht müde.", en = "Dwarf. Short legs, long stamina. Not tired yet.", stimme = "levelup-12", wenn = { rasse = "Dwarf" } },
      { de = "Taure. Groß, ruhig, schwer zu erschrecken. Genau richtig hier.", en = "Tauren. Big, calm, hard to spook. Just right for this.", stimme = "levelup-13", wenn = { rasse = "Tauren" } },
      { de = "Orc. Man sieht dir an, dass du das ernst nimmst.", en = "Orc. You clearly take this seriously.", stimme = "levelup-14", wenn = { rasse = "Orc" } },
    } },
    LOOT = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "veryhappy", pose = nil, halte = 15, cue = "oh", drossel = "3600", texte = {
      { de = "Blau! Zeig her.", en = "Blue! Show me.", stimme = "loot-1", wenn = nil },
      { de = "Das glänzt. Das behältst du.", en = "That sparkles. You're keeping that.", stimme = "loot-2", wenn = nil },
      { de = "Oh, das hat Runen drin. Echte. Behalten.", en = "Oh, that has runes in it. Real ones. Keep it.", stimme = "loot-3", wenn = nil },
      { de = "Selten. Und du hast es einfach so gefunden? Verdächtig glatt.", en = "Rare. And you just found it? Suspiciously smooth.", stimme = "loot-4", wenn = nil },
      { de = "Schöner Fund, {Meister|Meisterin}. Ich hätte es mir auch geholt.", en = "Nice find, my dear. I'd have grabbed it too.", stimme = "loot-5", wenn = nil },
      { de = "Das leuchtet von innen, {Held|Heldin}. Nicht verkaufen. Noch nicht.", en = "That glows from within, hero. Don't sell it. Not yet.", stimme = "loot-6", wenn = nil },
      { de = "Bei den Leylinien, Beute! Ich freu mich für dich. Und ein bisschen für mich.", en = "By the ley lines, loot! I'm happy for you. And a little for me.", stimme = "loot-7", wenn = nil },
    } },
    SKILL = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "smirk", pose = nil, halte = 10, cue = nil, drossel = "3600", texte = {
      { de = "{beruf} {wert}. Handwerk ist auch Magie, nur langsamer.", en = "{beruf} {wert}. Crafting is magic too, just slower.", stimme = nil, wenn = nil },
      { de = "Handwerk ist auch Magie, nur langsamer.", en = "Crafting is magic too, just slower.", stimme = "skill-1", wenn = nil },
      { de = "{beruf} steigt. Geduld ist auch ein Zauber, nur ohne Funken.", en = "{beruf} is climbing. Patience is a spell too, just without sparks.", stimme = nil, wenn = nil },
      { de = "Fleißig. Ich hätte das mit einem Fingerschnippen erledigt. Theoretisch.", en = "Diligent. I'd have done that with a snap of my fingers. In theory.", stimme = "skill-2", wenn = nil },
      { de = "Handwerk. Deine Hände lernen, was mein Kopf schon weiß.", en = "Crafting. Your hands are learning what my head already knows.", stimme = "skill-3", wenn = nil },
      { de = "Wieder ein Meilenstein. Du wirst noch nützlich, {mein Lieber|meine Liebe}.", en = "Another milestone. You're becoming useful, my dear.", stimme = "skill-4", wenn = nil },
      { de = "{wert}. Nicht schlecht für jemanden ohne Runenlehre.", en = "{wert}. Not bad for someone without rune training.", stimme = nil, wenn = nil },
    } },
