    PUNKT_GESETZT = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "smug", pose = nil, halte = 10, cue = nil, drossel = "keine", texte = {
      { de = "Markiert. Die Rune hält die Stelle fest, bis du zurückkommst.", en = "Marked. The rune holds this spot until you come back.", stimme = "punkt_gesetzt-1", wenn = nil },
