    PUNKT_OHNE_TOMTOM = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "hmm", pose = nil, halte = 10, cue = "hmm", drossel = "600", texte = {
      { de = "Ich hab's mir gemerkt. Einen Pfeil malen kann ich ohne TomTom aber nicht.", en = "I've noted it down. But without TomTom I can't draw you an arrow.", stimme = "punkt_ohne_tomtom-1", wenn = nil },
      { de = "„{titel}“ liegt in der Chronik. Für den Pfeil bräuchte ich TomTom.", en = "\"{titel}\" is in the chronicle. For the arrow I'd need TomTom.", stimme = nil, wenn = nil },
