    MOB_UNBEKANNT = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "hmm", pose = nil, halte = 10, cue = "hmm", drossel = "keine", texte = {
      { de = "Den kenne ich nicht. Nicht mal die Runen kennen den.", en = "Never heard of it. Not even the runes have.", stimme = "mob_unbekannt-1", wenn = nil },
      { de = "„{name}“? Steht in keiner Zeile, die ich lesen kann.", en = "\"{name}\"? Not in a single line I can read.", stimme = nil, wenn = nil },
