    MOB_OHNE_QUESTIE = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "whatever", pose = nil, halte = 10, cue = nil, drossel = "600", texte = {
      { de = "Ohne Questie ist die große Bibliothek zu. Und ich rate ungern.", en = "Without Questie the great library is shut. And I'd rather not guess.", stimme = "mob_ohne_questie-1", wenn = nil },
      { de = "Mir fehlt das Buch. Questie hat es, ich nicht.", en = "I'm missing the book. Questie has it, I don't.", stimme = "mob_ohne_questie-2", wenn = nil },
