    MOB_RIVALE_WARNUNG = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "alert", pose = nil, halte = 12, cue = nil, drossel = "npc-600", texte = {
      { de = "Vorsicht. Den kennen wir schon. Und nicht im Guten.", en = "Careful. We've met that one before. And not fondly.", stimme = "mob_rivale_warnung-1", wenn = nil },
      { de = "{name}. {n} Mal hat er dich fast gehabt, {Held|Heldin}. Diesmal nicht.", en = "{name}. It nearly had you {n} times, hero. Not this time.", stimme = nil, wenn = nil },
      { de = "{name} steht rot in meinem Bestiarium. Geh da nicht allein hin.", en = "{name} is written in red in my bestiary. Don't go there alone.", stimme = nil, wenn = nil },
