    QUEST_GEBER_GEFUNDEN = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "thinking", pose = nil, halte = 10, cue = nil, drossel = "keine", texte = {
      { de = "Der Auftraggeber steht auf der Karte. Pfeil folgt.", en = "The quest giver is on the map. Arrow follows.", stimme = "quest_geber_gefunden-1", wenn = nil },
      { de = "{name}, in {zone}. Dort fängt es an.", en = "{name}, in {zone}. That's where it starts.", stimme = nil, wenn = nil },
      { de = "„{titel}“ bekommst du bei {name}. Die Runen sind sich sicher.", en = "\"{titel}\" comes from {name}. The runes are certain.", stimme = nil, wenn = nil },
