    RUNEN_FEHLER = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "anxious", pose = nil, halte = 12, cue = nil, drossel = "flanke", texte = {
      { de = "Irgendwo sind mir die Runen durchgegangen. Nichts Schlimmes. Wahrscheinlich.", en = "Some runes got away from me somewhere. Nothing serious. Probably.", stimme = "runen_fehler-1", wenn = nil },
      { de = "{n} wildgewordene Runen im Sack. „/lyra runen“ zeigt sie dir.", en = "{n} runaway runes in the sack. \"/lyra runes\" will show you.", stimme = nil, wenn = nil },
      { de = "Eine Rune hat gezuckt. Ich fange sie wieder ein, keine Sorge.", en = "A rune twitched. I'll catch it again, don't worry.", stimme = "runen_fehler-2", wenn = nil },
