    KAMPF_REKORD = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "smug", pose = nil, halte = 12, cue = "hihi", drossel = "600", texte = {
      { de = "{dps} Schaden pro Sekunde. Dein Rekord. Ich hab mitgezaubert. Fast.", en = "{dps} damage per second. Your record. I cast along. Almost.", stimme = nil, wenn = nil },
