      { de = "Das war deutlich über deinem Schnitt. Ich sag nicht wie viel. Doch: {prozent} Prozent.", en = "That was well above your average. I won't say how much. Fine: {prozent} percent.", stimme = nil, wenn = nil },
      { de = "Heute geht dir das leichter von der Hand als sonst. Nur eine Beobachtung.", en = "Today this comes easier to you than usual. Just an observation.", stimme = "kampf_schnitt-1", wenn = nil },
