    } },
    SCHADEN_ERLITTEN_HOCH = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "concerned", pose = nil, halte = 14, cue = "seufz", drossel = "600", texte = {
      { de = "Du hast {prozent} Prozent mehr eingesteckt als üblich. Das war kein guter Handel.", en = "You took {prozent} percent more than usual. That wasn't a good trade.", stimme = nil, wenn = nil },
